// ValidateHttpHeaderWithDepth validates HttpHeader and carries nested-message depth across
// generated package boundaries.
func ValidateHttpHeaderWithDepth(m *HttpHeader, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate Name (assert_required)
	if m.Name == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field Name is required")
	}

	// Validate Name (assert_max_length: 256)
	if len(m.Name) > 256 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Name must be at most 256 characters, got: %d", len(m.Name))
	}

	// Validate Value (assert_max_length: 8192)
	if len(m.Value) > 8192 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Value must be at most 8192 characters, got: %d", len(m.Value))
	}

	// Validate Name (default max size: 32768 bytes)
	if len(m.Name) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Name exceeds max size of 32768 bytes, got: %d", len(m.Name))
	}

	// Validate Value (default max size: 32768 bytes)
	if len(m.Value) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Value exceeds max size of 32768 bytes, got: %d", len(m.Value))
	}

	return nil
}

