	if _, ok := HttpMethod_name[int32(m.Method)]; !ok {
		return protoerrors.NewErrMissingInvalidData(nil, "field Method has unknown enum value %d", int32(m.Method))
	}

	// Validate Headers nested messages
	for i, val := range m.Headers {
		if err := ValidateHttpHeaderWithDepth(val, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Headers[%d] validation failed", i)
		}
	}

